const ele = s => { const k = s.indexOf('|'), out = []; let q = +s.slice(0, k); out.push(q / 10);
  for (let i = k + 1; i < s.length; i++) { if (s[i] === '!') { const j = s.indexOf(',', i); q += +s.slice(i + 1, j); i = j; } else q += s.charCodeAt(i) - 79; out.push(q / 10); }
  return out; };
const line = s => { const out = []; let i = 0, a = 0, b = 0;
  const num = () => { let r = 0, sh = 0, c; do { c = s.charCodeAt(i++) - 63; r |= (c & 0x1f) << sh; sh += 5; } while (c >= 0x20); return r & 1 ? ~(r >> 1) : r >> 1; };
  while (i < s.length) { a += num(); b += num(); out.push([a / 1e5, b / 1e5]); }
  return out; };
